#!/usr/bin/env python3
"""Execute all five criteria with full evidence and explicit corpus eligibility."""
import argparse
from datetime import datetime, timezone
import hashlib
import json
import math
import statistics
import sys
import uuid

import requests
import config
import scenarios

LABELS = {
    'human': 'This writing appears more likely to have been written by a person, but the estimate may be wrong.',
    'unsure': "We can't tell reliably how this writing was created. You can appeal this assessment.",
    'ai': 'This writing may have been generated by AI. This is an estimate and can be appealed.',
}


def request_json(url, method, endpoint, body=None, timeout=90):
    result = {'method': method, 'endpoint': endpoint, 'request': body, 'status': None}
    try:
        response = requests.request(method, url + endpoint, json=body, timeout=timeout)
        result['status'] = response.status_code
        try:
            result['response'] = response.json()
        except ValueError:
            result['error'] = 'Response was not JSON'
            result['response_text'] = response.text
    except requests.RequestException as exc:
        result['error'] = f'{type(exc).__name__}: {exc}'
    return result


def valid_decision(record):
    p = record.get('response')
    if record.get('status') != 200 or not isinstance(p, dict):
        return False
    numbers = [p.get(k) for k in ('confidence', 'model_score', 'style_score')]
    return (isinstance(p.get('content_id'), str) and bool(p['content_id'])
            and isinstance(p.get('label'), str)
            and p.get('guess') in LABELS
            and all(isinstance(v, (int, float)) and not isinstance(v, bool)
                    and math.isfinite(v) and 0 <= v <= 1 for v in numbers))


def expected_guess(score, settings):
    if score >= settings['ai_threshold']:
        return 'ai'
    if score <= settings['human_threshold']:
        return 'human'
    return 'unsure'


def measure(scenario, records, entries, settings, audit_ok=True):
    kind = scenario['kind']
    if kind == 'invalid':
        matches = 0
        for r in records:
            creator = r['request']['creator_id']
            p = r.get('response') if isinstance(r.get('response'), dict) else {}
            no_decision = not any(e.get('creator_id') == creator and e.get('guess') is not None for e in entries)
            if r['status'] == 400 and p.get('error') == 'invalid_input' and no_decision:
                matches += 1
        return {'accepted_checks': matches, 'total': 5, 'passed': matches == 5 and audit_ok}
    decisions = [r for r in records if r.get('endpoint') == '/submit']
    valid = all(valid_decision(r) for r in decisions)
    if not valid:
        return {'passed': False, 'error': 'At least one submission did not return a complete decision.'}
    payloads = [r['response'] for r in decisions]
    if kind == 'false_positive':
        flags = sum(p['guess'] == 'ai' for p in payloads)
        return {'ai_flags_on_reference_fixtures': flags, 'total': len(payloads), 'passed': len(payloads) == 10 and flags <= 1}
    if kind == 'separation':
        reference = [r['response']['confidence'] for r in decisions if r['sample_id'].startswith('R')]
        comparison = [r['response']['confidence'] for r in decisions if r['sample_id'].startswith('C')]
        if len(reference) != 10 or len(comparison) != 10:
            return {'passed': False, 'error': 'Expected ten results in each group.'}
        gap = statistics.mean(comparison) - statistics.mean(reference)
        return {'reference_mean': statistics.mean(reference), 'comparison_mean': statistics.mean(comparison),
                'gap': gap, 'passed': gap >= .15}
    if kind == 'coverage':
        guesses = sorted(set(p['guess'] for p in payloads))
        matches = all(p['guess'] == expected_guess(p['confidence'], settings)
                      and p['label'] == LABELS[p['guess']] for p in payloads)
        return {'guesses': guesses, 'label_and_range_match': matches,
                'passed': guesses == ['ai', 'human', 'unsure'] and matches and len(payloads) <= 30}
    if kind == 'appeals':
        appeals = [r for r in records if r['endpoint'] == '/appeal']
        successful = 0
        for r in appeals:
            body = r['request']
            p = r.get('response') if isinstance(r.get('response'), dict) else {}
            history = [e for e in entries if e.get('content_id') == body['content_id']]
            decisions_for_id = [e for e in history if e.get('status') == 'decided']
            appeal_events = [e for e in history if e.get('event') == 'appeal']
            original = next((d['response'] for d in decisions if d['response']['content_id'] == body['content_id']), None)
            if (r['status'] == 200 and p.get('content_id') == body['content_id'] and p.get('status') == 'under_review'
                    and len(decisions_for_id) == 1 and len(appeal_events) == 1
                    and appeal_events[0]['reasoning'] == body['reasoning']
                    and history[-1]['status'] == 'under_review' and original
                    and decisions_for_id[0]['guess'] == original['guess']
                    and decisions_for_id[0]['combined_score'] == original['confidence']
                    and history.index(decisions_for_id[0]) < history.index(appeal_events[0])):
                successful += 1
        return {'recorded_appeals': successful, 'total': 5, 'passed': successful == 5 and audit_ok}
    raise ValueError(kind)


def run_trial(url, scenario, trial, namespace, timeout, settings):
    before = request_json(url, 'GET', '/log', timeout=timeout)
    records = []
    for i, sample in enumerate(scenario.get('samples', scenario.get('bodies', [])), 1):
        creator = f'eval_{namespace}_c{scenario["criterion"]}_t{trial}_{i}'
        if scenario['kind'] == 'invalid':
            body = {**sample, 'creator_id': creator}
        else:
            body = {'text': sample['text'], 'creator_id': creator}
        r = request_json(url, 'POST', '/submit', body, timeout)
        r['sample_id'] = sample.get('id', f'bad_{i}')
        records.append(r)
        if scenario['kind'] == 'appeals' and valid_decision(r):
            body = {'content_id': r['response']['content_id'], 'reasoning': f'Review request {namespace}, trial {trial}, item {i}.'}
            records.append(request_json(url, 'POST', '/appeal', body, timeout))
    after = request_json(url, 'GET', '/log', timeout=timeout)
    audit_ok = all(r['status'] == 200 and isinstance(r.get('response'), dict)
                   and isinstance(r['response'].get('entries'), list) for r in (before, after))
    entries = after['response']['entries'][len(before['response']['entries']):] if audit_ok else []
    measurement = measure(scenario, records, entries, settings, audit_ok)
    return {'trial': trial, 'measurement': measurement, 'requests': records, 'audit_entries': entries,
            'audit_available': audit_ok}


def metric_text(measurement):
    if 'error' in measurement:
        return 'ERROR'
    if 'ai_flags_on_reference_fixtures' in measurement:
        return f"{measurement['ai_flags_on_reference_fixtures']}/10 flags (fixture metric)"
    if 'gap' in measurement:
        return f"gap {measurement['gap']:.4f} (fixture metric)"
    if 'guesses' in measurement:
        return f"{len(measurement['guesses'])}/3 labels; match={measurement['label_and_range_match']}"
    return f"{measurement.get('recorded_appeals', measurement.get('accepted_checks'))}/5"


def write_report(data, path):
    lines = ['# Criteria run: ' + data['label'], '', 'Produced by `run_eval.py::main`, `run_trial`, and `measure`.', '',
             'Criteria 1 and 2 retain their original personal-authorship prerequisite. The fixture metrics below do not establish it.', '',
             '| Criterion | Target | Run 1 | Run 2 | Run 3 | Verdict |', '|---|---|---|---|---|---|']
    for row in data['criteria']:
        texts = [metric_text(t['measurement']) for t in row['trials']]
        lines.append('| ' + ' | '.join([str(row['criterion']) + '. ' + row['name'], row['target'], *texts, row['verdict']]) + ' |')
    for row in data['criteria']:
        lines += ['', f'## Criterion {row["criterion"]}: {row["name"]}', '', row.get('eligibility_note', '')]
        for trial in row['trials']:
            lines += ['', f'### Trial {trial["trial"]}', '', '```json', json.dumps(trial, indent=2), '```']
    path.with_suffix('.md').write_text('\n'.join(lines) + '\n', encoding='utf-8')
    path.with_suffix('.json').write_text(json.dumps(data, indent=2), encoding='utf-8')


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument('--label', default='before')
    parser.add_argument('--trials', type=int, default=3)
    parser.add_argument('--url', default=f'http://{config.HOST}:{config.PORT}')
    parser.add_argument('--timeout', type=float, default=90)
    args = parser.parse_args()
    problems = scenarios.validate()
    if problems:
        raise SystemExit('; '.join(problems))
    if args.trials != 3:
        raise SystemExit('Exactly three trials are required for this evaluation.')
    health = request_json(args.url, 'GET', '/health', timeout=5)
    if health['status'] != 200:
        raise SystemExit('Start the service before running the evaluation.')
    settings = {'human_threshold': config.HUMAN_THRESHOLD, 'ai_threshold': config.AI_THRESHOLD,
                'model_weight': config.WEIGHT_MODEL_SIGNAL, 'style_weight': config.WEIGHT_STYLE_SIGNAL}
    stamp = datetime.now(timezone.utc).strftime('%Y%m%dT%H%M%S%fZ')
    namespace = uuid.uuid4().hex[:10]
    data = {'label': args.label, 'started_utc': stamp, 'settings': settings,
            'corpus_sha256': hashlib.sha256(scenarios.CORPUS_PATH.read_bytes()).hexdigest(),
            'criteria': []}
    for scenario in scenarios.SCENARIOS:
        row = {k: scenario[k] for k in ('criterion', 'name', 'target')}
        row['trials'] = []
        for trial in range(1, 4):
            t = run_trial(args.url, scenario, trial, namespace, args.timeout, settings)
            row['trials'].append(t)
            print(f"Criterion {scenario['criterion']}, trial {trial}: {metric_text(t['measurement'])}", flush=True)
        if not scenario.get('original_eligible', True):
            row['verdict'] = 'NOT EVALUATED'
            row['eligibility_note'] = 'Personal-writing prerequisite is unverified. These are supplemental fixture measurements, not a verdict on the original authorship criterion.'
        else:
            row['verdict'] = 'MET' if all(t['measurement']['passed'] for t in row['trials']) else 'MISSED'
        data['criteria'].append(row)
    config.RESULTS_DIR.mkdir(exist_ok=True)
    path = config.RESULTS_DIR / f'run_{stamp}_{args.label}'
    write_report(data, path)
    print(f'Wrote {path}.json and .md', flush=True)


if __name__ == '__main__':
    main()
